        cell = ws_task.cell(row=row_num, column=col)
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value!r}")

# Check if there's a row 10 with specific content
print("\n=== Check rows 9-10 with all columns ===")
for row_num in [9, 10]:
    vals = []
    for col in range(1, 15):
        cell = ws_task.cell(row=row_num, column=col)
        vals.append(f"{cell.coordinate}={cell.value!r}")
    print(f"Row {row_num}: {vals}")

# Check yellow cells - look at fill colors of target cells
print("\n=== Cell fill colors for H12:L12 ===")
